1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
45	  sword: 100,
46	  staff: 80,
47	  amulet: 60,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const FIRST_INSURANCE_PERCENT = 10;
54	
55	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
56	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
57	// is 110.00000000000001 in binary floating point. Since the final amount feeds
58	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
59	const percentOf = (amount: number, percent: number): number =>
60	  (amount * percent) / 100;
61	
62	const addPercent = (amount: number, percent: number): number =>
63	  amount + percentOf(amount, percent);
64	
65	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
66	
67	const BLOCK_SIZE = 3;
68	const BLOCK_BASE_PREMIUM = 60;
69	
70	const sumItemBasePremiums = (items: Item[]): number =>
71	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
72	
73	/** Items of one and the same type, e.g. the three runes that form a block. */
74	type TypeGroup = Item[];
75	
76	const groupByType = (items: Item[]): TypeGroup[] => [
77	  ...items
78	    .reduce(
79	      (groups, item) =>
80	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
81	      new Map<string, TypeGroup>(),
82	    )
83	    .values(),
84	];
85	
86	const formsBlock = (group: TypeGroup): boolean => group.length === BLOCK_SIZE;
87	
88	const groupBasePremium = (group: TypeGroup): number =>
89	  formsBlock(group) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(group);
90	
91	const policyBasePremium = (items: Item[]): number =>
92	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
93	
94	const CURSE_PERCENT = 50;
95	const HIGH_ENCHANTMENT_PERCENT = 30;
96	const HIGH_ENCHANTMENT_THRESHOLD = 5;
97	
98	/**
99	 * Item-scoped modifiers apply to the affected item's own base premium, not to
100	 * the policy total. Each entry contributes its percentage independently, so
101	 * several modifiers on one item add up rather than compounding.
102	 */
103	const ITEM_SURCHARGE_PERCENTS: { applies: (item: Item) => boolean; percent: number }[] = [
104	  { applies: (item) => item.cursed === true, percent: CURSE_PERCENT },
105	  {
106	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
107	    percent: HIGH_ENCHANTMENT_PERCENT,
108	  },
109	];
110	
111	const itemSurcharge = (item: Item): number =>
112	  ITEM_SURCHARGE_PERCENTS.filter(({ applies }) => applies(item)).reduce(
113	    (surcharge, { percent }) => surcharge + percentOf(itemBasePremium(item), percent),
114	    0,
115	  );
116	
117	const totalItemSurcharges = (items: Item[]): number =>
118	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
119	
120	const quotePremium = (step: QuoteStep): number =>
121	  Math.ceil(
122	    addPercent(policyBasePremium(step.items), FIRST_INSURANCE_PERCENT) +
123	      totalItemSurcharges(step.items) +
124	      PROCESSING_FEE,
125	  );
126	
127	const runStep = (step: Step): StepResult => {
128	  if (step.op === "quote") return { premium: quotePremium(step) };
129	  throw new Error(`Unsupported step: ${step.op}`);
130	};
131	
132	export const runScenario = (scenario: Scenario): ScenarioResult => ({
133	  results: scenario.steps.map(runStep),
134	});
